// @generated by `cargo xtask tokens` from design/tokens/adage.tokens.json. Do not edit.
// The mod's half of the design tokens (docs/design/style.md): glyphs with their ASCII twins
// (`ADAGE_ASCII=1` picks the twin) and Adage's roles as Claude Code theme keys.

/** Glyphs as `[unicode, ascii]`; every one is one column wide. */
export const GLYPHS = {
  /** The active step. */
  active: ["◆", "*"],
  /** Directs to. */
  arrow: ["→", "->"],
  /** A procedure card: the steps and files of a recurring task. */
  card: ["▤", "[=]"],
  /** A finished step. */
  done: ["◇", "+"],
  /** Failed. */
  fail: ["✗", "x"],
  /** An instinct: born with it. */
  instinct: ["◉", "(o)"],
  /** A strength lamp. */
  lamp: ["●", "*"],
  /** A notice: the one line shown at session start. */
  notice: ["»", ">>"],
  /** Nascent, not configured, or withheld. */
  off: ["○", "o"],
  /** Done, followed, met. */
  ok: ["✓", "+"],
  /** The selected choice. */
  pointer: ["›", ">"],
  /** Quiet: uplift below the bar; waits for a person. */
  quiet: ["◌", "(.)"],
  /** The flow rail. */
  rail: ["│", "|"],
  /** A reflex: the learned arc. */
  reflex: ["◠", "~"],
  /** A rewrite: the command was changed before it ran. */
  rewrite: ["↪", "=>"],
  /** Separator between facts. */
  sep: ["·", "-"],
  /** From a skill (`adage train`). */
  skill: ["◈", "<>"],
} as const

export type GlyphName = keyof typeof GLYPHS

/** A glyph, or its ASCII twin. */
export function glyph(name: GlyphName, ascii: boolean): string {
  return GLYPHS[name][ascii ? 1 : 0]
}

/** Adage's roles as the engine's theme keys: `Text` takes these, never a colour. */
export const ROLES = {
  /** `color.ink.1`: Body text and headlines. The terminal uses its own default foreground. */
  ink: "text",
  /** `color.ink.2`: Secondary text and captions. */
  ink2: "inactive",
  /** `color.ink.3`: Tertiary text: labels, timestamps, the control arm. */
  ink3: "subtle",
  /** `color.accent.base`: The one brand hue: focus, selection, the active step, links. */
  accent: "suggestion",
  /** `color.accent.soft`: Accent text: commands, key hints. */
  command: "permission",
  /** `color.lamp.fire`: Strength fire (do this); also success. */
  fire: "success",
  /** `color.lamp.prime`: Strength prime (consider this); also warnings. */
  prime: "warning",
  /** `color.lamp.inhibit`: Strength inhibit (a dead end); also errors. */
  inhibit: "error",
  /** `color.cost`: GPU spend and cost, nothing else. */
  cost: "claude",
} as const

export type Role = keyof typeof ROLES
